import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Pumpkin Market update checks","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/update-check/docs/index.md"},"headers":[],"relativePath":"tools/update-check/docs/index.md","filePath":"tools/update-check/docs/index.md","lastUpdated":1792351626000}`),a={name:`tools/update-check/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="pumpkin-market-update-checks" tabindex="-1">Pumpkin Market update checks <a class="header-anchor" href="#pumpkin-market-update-checks" aria-label="Permalink to “Pumpkin Market update checks”">​</a></h1><p><code>@pumpkin-plugins/update-check</code> compares a plugin&#39;s version with its Pumpkin Market listing using Pumpkin&#39;s WASI HTTP host. The registration helper schedules the request so plugin loading and game ticks are not blocked.</p><h2 id="register-an-automatic-check" tabindex="-1">Register an automatic check <a class="header-anchor" href="#register-an-automatic-check" aria-label="Permalink to “Register an automatic check”">​</a></h2><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { registerPluginWithUpdates } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@pumpkin-plugins/update-check&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">registerPluginWithUpdates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(plugin, info, { schedule });</span></span></code></pre></div><p>The plugin must declare the HTTP WASI capability and request the <code>http.outbound</code> permission. The scheduler must run its callback in a later task, not inline. Export and dispatch the scheduled task handler as part of the plugin entry point so follow-up polling can proceed.</p><h2 id="failure-behavior-and-direct-checks" tabindex="-1">Failure behavior and direct checks <a class="header-anchor" href="#failure-behavior-and-direct-checks" aria-label="Permalink to “Failure behavior and direct checks”">​</a></h2><p>Automatic checks do not block plugin startup. A failed request is logged and does not prevent the plugin from loading.</p><p>Asynchronous requests time out after 15 seconds. Response bodies larger than 64 KiB are rejected.</p><p><code>marketplaceUrl</code> can override the Market base URL for tests or alternate environments.</p><p><code>checkMarketUpdate</code> supports a synchronous injected JSON requester for deterministic code and tests. <code>requestMarketJsonAsync</code> exposes the non-blocking transport directly. The synchronous <code>requestMarketJson</code> blocks, so do not call it during plugin loading or a server tick.</p><p>When Market returns optional <code>release_notes</code>, the checker converts its Markdown to plain text for the update notice. The current Market check endpoint does not return this field; a Market API update must add it before plugins can show changelogs.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};